//--------------------------------------------------------------------------//
//! \desc  Use this method to unlink a Reg_Func from an id key
//!        

//! \assume Reg_Table is a valid pointer

//! \notes  Public method.

//! \param  reg       the Reg_Table object
//! \param  id        the Reg_Id key 

//! \return /b Boolean  TRUE : Reg_Func succesfully removed
//!                     FALSE: Reg_Func or Reg_Id key not found
//--------------------------------------------------------------------------//

Boolean reg_rem_func( Reg_Table reg  , Reg_Id id , Reg_Func func  )
{
    Boolean ret = FALSE ; 
    
	Reg_Table_Id table_id = NULL ;

    if( reg_atomic_request( reg ) )
    {                
        table_id = reg_check_id( reg , id );

        if( table_id != NULL )
        {            
            Reg_Obj_Without_Data curr = table_id->next_reg_obj ;
            
            while( curr )
            {
                if( curr->func == func)
                {
                    curr->func = NULL ;

                    ret = TRUE ;
                }
                
                curr = curr->next ;
            }
        }
                           
        reg_atomic_release( reg );
    }

    return ret ;
}

